import { NextResponse } from "next/server";
import { appUrl, getStripe } from "@/lib/stripe";
import { getCurrentUser, updateUserBilling } from "@/lib/users";

// Starts a Stripe Checkout session for the monthly Pro plan.
export async function POST() {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ error: "Not signed in" }, { status: 401 });
  }
  if (user.plan === "pro") {
    return NextResponse.redirect(`${appUrl()}/dashboard`, 303);
  }

  const priceId = process.env.STRIPE_PRO_PRICE_ID;
  if (!priceId) {
    return NextResponse.json({ error: "Billing not configured" }, { status: 500 });
  }

  const stripe = getStripe();

  let customerId = user.stripeCustomerId;
  if (!customerId) {
    const customer = await stripe.customers.create({
      email: user.email,
      name: user.name,
      metadata: { userId: user.id },
    });
    customerId = customer.id;
    await updateUserBilling(user.id, { stripeCustomerId: customerId });
  }

  const session = await stripe.checkout.sessions.create({
    mode: "subscription",
    customer: customerId,
    client_reference_id: user.id,
    line_items: [{ price: priceId, quantity: 1 }],
    subscription_data: { metadata: { userId: user.id } },
    success_url: `${appUrl()}/dashboard?checkout=success`,
    cancel_url: `${appUrl()}/dashboard?checkout=cancelled`,
  });

  if (!session.url) {
    return NextResponse.json({ error: "No checkout URL" }, { status: 502 });
  }
  // 303 so the browser follows the form POST with a GET.
  return NextResponse.redirect(session.url, 303);
}
EOF
