import type Stripe from "stripe";
import { NextResponse } from "next/server";
import { getStripe } from "@/lib/stripe";
import { getUserByStripeCustomerId, updateUserBilling } from "@/lib/users";

export const runtime = "nodejs";

function customerIdOf(c: string | Stripe.Customer | Stripe.DeletedCustomer | null) {
  return typeof c === "string" ? c : c?.id;
}

export async function POST(req: Request) {
  const secret = process.env.STRIPE_WEBHOOK_SECRET;
  const signature = req.headers.get("stripe-signature");
  if (!secret || !signature) {
    return NextResponse.json({ error: "Missing signature" }, { status: 400 });
  }

  // Signature verification needs the raw, unparsed body.
  const body = await req.text();
  let event: Stripe.Event;
  try {
    event = getStripe().webhooks.constructEvent(body, signature, secret);
  } catch {
    return NextResponse.json({ error: "Invalid signature" }, { status: 400 });
  }

  switch (event.type) {
    case "checkout.session.completed": {
      const session = event.data.object;
      // Only upgrade once the money has actually been collected.
      if (session.mode !== "subscription" || session.payment_status !== "paid") break;
      const userId = session.client_reference_id;
      if (!userId) break;
      const subscription =
        typeof session.subscription === "string"
          ? session.subscription
          : session.subscription?.id;
      await updateUserBilling(userId, {
        plan: "pro",
        stripeCustomerId: customerIdOf(session.customer),
        stripeSubscriptionId: subscription,
      });
      break;
    }
    case "customer.subscription.updated":
    case "customer.subscription.deleted": {
      const sub = event.data.object;
      const customerId = customerIdOf(sub.customer);
      const user = customerId ? await getUserByStripeCustomerId(customerId) : undefined;
      if (!user) break;
      const active = sub.status === "active" || sub.status === "trialing";
      await updateUserBilling(user.id, {
        plan: active ? "pro" : "free",
        stripeSubscriptionId: active ? sub.id : undefined,
      });
      break;
    }
  }

  return NextResponse.json({ received: true });
}
EOF
